  if(action==='new-connection'||action==='edit-connection'){modalKind='connections';modalRecord=action==='edit-connection'?find('connections',id):null;modal(modalRecord?'Sửa kênh kết nối':'Thêm kênh mới',`<form id="record-form"><div class="form-error"></div>${select('Nền tảng','provider',Object.entries(S.providers).map(([k,v])=>[k,v.label]),modalRecord?.provider||'zalo_personal')}<p class="help-text" id="provider-hint" style="margin-top:-10px;margin-bottom:15px">${e(S.providers[modalRecord?.provider||'zalo_personal'].hint)}${(modalRecord?.provider||'zalo_personal')==='zalo_personal'?` <a href="#" data-action="toggle-zalo-guide" style="color:var(--primary);text-decoration:none" title="Xem hướng dẫn chi tiết">${icon("help", 15)}</a>`:''}</p><div id="zalo-guide-content" style="display:none;background:var(--surface-sunken);padding:12px;border-radius:8px;margin-top:-5px;margin-bottom:15px;font-size:13px"><p style="margin:0 0 8px 0;font-weight:600">Cách lấy Cookie Zalo Web:</p><ol style="margin:0;padding-left:20px;line-height:1.5"><li>Mở tab mới, vào <strong>chat.zalo.me</strong> và đăng nhập.</li><li>Bấm <strong>F12</strong> mở DevTools &gt; chọn tab <strong>Network</strong>.</li><li>Bấm <strong>F5</strong> tải lại trang.</li><li>Bấm vào một request bất kỳ (ví dụ: <code>sticker_detail</code>, <code>poll</code>...).</li><li>Bên phải chọn tab <strong>Headers</strong> &gt; <strong>Request Headers</strong>.</li><li>Tìm dòng <strong>cookie:</strong>, chuột phải vào giá trị dài ngoằng đó chọn <strong>Copy value</strong> rồi dán vào ô Token bên dưới.</li></ol></div>${field('Tên hiển thị (Tự do)','name',modalRecord?.name||'','text','required')}${select('Chế độ','mode',[['api','API thực tế'],['demo','Dữ liệu mẫu'],['assisted','Hỗ trợ đăng thủ công']],modalRecord?.mode||'assisted')}<div class="api-fields ${modalRecord?.mode==='api'?'':'hidden'}">${field('Access Token / API Key / Zalo Cookie (Tùy kênh)','token',modalRecord?.token||'','text','placeholder="Nhập token..."')}${field('Account ID / Page ID (Tùy kênh)','accountId',modalRecord?.accountId||'','text','placeholder="ID..."')}${field('Cấu hình API bổ sung (JSON)','config',modalRecord?.config||'','text','placeholder="{}"')}</div></form>`,formFooter(modalRecord?'Lưu thay đổi':'Thêm kênh','record-form'));return;}
