function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
document.addEventListener('change',async event=>{const el=event.target;try{
 if(el.id==='content-upload'){await uploadFiles([...el.files],true);el.value='';return;}
 if(el.name==='provider'&&modalKind==='connections'){$('#provider-hint').innerHTML=e(S.providers[el.value].hint)+(el.value==='zalo_personal'?` <a href="#" data-action="toggle-zalo-guide" style="color:var(--primary);text-decoration:none" title="Xem hướng dẫn chi tiết">${icon("help", 15)}</a>`:'');const g=$('#zalo-guide-content');if(g)g.style.display='none';}
 if(el.name==='mode'&&modalKind==='connections')$('.api-fields').classList.toggle('hidden',el.value!=='api');
 if(el.name==='carrier'&&$('#ghn-fields'))$('#ghn-fields').classList.toggle('hidden',el.value!=='ghn');
 if(el.name==='productSelector'&&el.value){const found=orderItems.find(i=>i.productId===el.value);if(found)found.quantity++;else orderItems.push({productId:el.value,quantity:1});el.value='';renderOrderItems();}
 if(el.name==='customerId'&&$('#order-form')){const c=find('customers',el.value);$('#order-form').phone.value=c?.phone||'';$('#order-form').address.value=c?.address||'';}
 if(el.classList.contains('item-quantity')){const q=Number(el.value);if(!Number.isInteger(q)||q<1){el.value=1;throw new Error('Số lượng ít nhất là 1.');}orderItems.find(i=>i.productId===el.dataset.id).quantity=q;renderOrderItems();}
 if(el.classList.contains('workflow-toggle')){const w=find('workflows',el.dataset.id);await api('/records/workflows/'+w.id,{method:'PATCH',body:{enabled:el.checked,version:w.version}});await refresh();}
 if(el.classList.contains('task-toggle')){const t=find('tasks',el.dataset.id);await api('/records/tasks/'+t.id,{method:'PATCH',body:{status:el.checked?'done':'open',version:t.version}});await refresh();}
 if(el.id==='assignee-select'){const c=find('conversations',el.dataset.id);await api('/conversations/'+c.id,{method:'PATCH',body:{assignee:el.value,version:c.version}});await refresh();}
 }catch(err){toast(err.message,true);}});
let searchTimer;document.addEventListener('input',event=>{const el=event.target;if(el.id==='page-search'){query=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const search=$('#page-search');search?.focus();search?.setSelectionRange(query.length,query.length);},180);}
 if(el.name==='caption'&&$('#preview-caption')){$('#preview-caption').textContent=el.value;$('#char-count').textContent=el.value.length+' ký tự';}
 if(['discount','shippingFee'].includes(el.name))updateTotals();
});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if(event.key==='Tab'&&$('.modal')){const focusables=$$('.modal button:not(:disabled),.modal input:not([type=hidden]),.modal select,.modal textarea,.modal a[href]').filter(el=>el.offsetParent!==null);const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
 if(event.key==='Enter'&&event.target.id==='global-search'){event.preventDefault();const q=event.target.value;route='content';location.hash='content';setTimeout(()=>{query=q;render();},30);}
});
setInterval(async()=>{if(!S||document.body.dataset.mediaUploading||$('.modal')||document.activeElement?.matches('input,textarea,select')||['inbox','phacdo'].includes(route))return;try{await refresh();}catch{}},15000);
