initConversationTags({get state(){return S;},api,refresh,render,modal,closeModal,toast});
initCare({get state(){return S;},api,refresh,refreshInbox,render,modal,closeModal,toast});
const loadInbox=initInbox({get state(){return S;},route:()=>route,api,refresh,render,modal,closeModal,toast,openConversation:id=>{selectedConversation=id;route='inbox';location.hash='inbox';render();}});

initMedia({get state(){return S;},api,refresh,render,modal,closeModal,toast,newPost:id=>{contentModal();draftAssets=[id];$('#upload-list').innerHTML=assetPreviews();$('#preview-media').innerHTML=thumb({assets:draftAssets},'card-cover');},attachChat:(c,id)=>{selectedConversation=c;route='inbox';location.hash='inbox';attachLibraryMedia(c,id);render();}});
initBot({get state(){return S;},route:()=>route,api,refresh,render,modal,closeModal,toast,openConversation:id=>{selectedConversation=id;route='inbox';location.hash='inbox';render();}});
boot();

let notificationUser='',notificationSeen=new Set();
setInterval(async()=>{if(!S?.user)return;if(notificationUser!==S.user.id){notificationUser=S.user.id;notificationSeen=new Set(S.notifications.map(n=>n.id));}const userId=S.user.id;try{const rows=await api('/notifications');if(S?.user?.id!==userId)return;S.notifications=rows;const button=document.querySelector('[data-action=notifications]');if(button){let dot=button.querySelector('.notification-dot');if(rows.some(n=>!n.read)&&!dot){dot=document.createElement('i');dot.className='notification-dot';dot.style.cssText='position:absolute;top:5px;right:5px;background:red;width:8px;height:8px;border-radius:50%';button.append(dot);}if(!rows.some(n=>!n.read))dot?.remove();}for(const n of rows){if(!notificationSeen.has(n.id)&&!n.read&&n.id.startsWith('chat-reminder:'))toast(n.title+': '+n.body);notificationSeen.add(n.id);}}catch{}},10000);
